(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const D=()=>window.BoraExamData,L=id=>window.BoraCourses[0].lessons.find(l=>l.id===id),uid=()=>crypto.randomUUID();let cleanup=()=>{};function stop(){cleanup();cleanup=()=>{}}const state=u=>(u.assessment??={lessonTests:{}});const record=(u,id)=>(state(u).lessonTests??={})[id]??=( {history:[]} );
function remaining(a,now=Date.now()){return a?.deadlineAt?Math.max(0,Date.parse(a.deadlineAt)-now):null}const time=ms=>{const n=Math.max(0,Math.ceil(ms/1000));return `${Math.floor(n/3600)?Math.floor(n/3600)+':':''}${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`};
function newWritten(mode,now=Date.now()){return {id:uid(),version:D().version,mode,index:0,startedAt:new Date(now).toISOString(),deadlineAt:mode==='timed'?new Date(now+D().writtenSeconds*1000).toISOString():null,answers:{},plays:{}}}function finishWritten(a,now=Date.now()){if(a.finishedAt)return;a.finishedAt=new Date(now).toISOString();a.expired=a.deadlineAt?now>=Date.parse(a.deadlineAt):false;a.fullAnswers=D().tasks.every(t=>String(a.answers[t.id]||'').trim())}
function oralStage(a,now=Date.now()){return a.mode==='timed'?Math.min(3,Math.floor(Math.max(0,now-Date.parse(a.startedAt))/300000)):Math.min(3,a.stage||0)}function newOral(mode,now=Date.now()){return {id:uid(),version:D().version,mode,stage:0,startedAt:new Date(now).toISOString(),deadlineAt:mode==='timed'?new Date(now+D().oralSeconds*1000).toISOString():null,messages:[],draft:''}}function finishOral(a,now=Date.now()){if(a.finishedAt)return;a.finishedAt=new Date(now).toISOString();a.stagesAnswered=[0,1,2,3].filter(stage=>a.messages.some(m=>m.role==='user'&&m.stage===stage));a.fullFormat=a.mode==='timed'&&now-Date.parse(a.startedAt)>=1200000&&a.stagesAnswered.length===4}
function progress(u){const tests=Object.entries(u.assessment?.lessonTests||{}).filter(([,r])=>r.last);return `<section class="assessment-summary"><h2>Проверки знаний</h2><p>Тем проверено: ${tests.length} из 30 · Закреплено по результату последней попытки: ${tests.filter(([,r])=>r.last.passed).length}.</p>${tests.slice(-3).map(([id,r])=>`<p><a href="#test/${esc(id)}">${esc(L(id)?.title||'Урок')}</a> · ${r.last.correct} из ${r.last.total}</p>`).join('')}<a class="btn alt" href="#exam">Общий пробный экзамен →</a><p class="small">Результаты Bora учебные: они не подтверждают CEFR, Celpe-Bras или готовность к натурализации.</p></section>`}
const sources=()=>'';
function quizPage(u,id){const l=L(id);if(!l)return '<div class="panel"><h1>Выбери урок</h1><a href="#courses/pt">Программа</a></div>';const r=record(u,id),a=r.draft,bank=window.BoraLessonTests.bank(id);let body;if(!a){body=`<p>Пять заданий на понимание, выбор фразы и короткий письменный ответ. Подсказки и разбор появятся после завершения.</p><p class="small">Для отметки «Закреплено» нужно 4 из 5. Это внутренний ориентир Bora. В заданиях с пропуском нужен указанный образец, а не любая возможная фраза.</p><button class="btn" id="test-start">${r.last?'Пройти ещё раз':'Начать тест'}</button>${r.last?`<section class="test-result"><h2>Последний результат: ${r.last.correct} из ${r.last.total}</h2><p>${r.last.passed?'Тема закреплена в этой проверке.':'Есть что повторить — ошибки помогут выбрать следующий шаг.'}</p>${r.last.results.map(v=>{const q=bank.find(q=>q.id===v.id);return q?`<details><summary>${v.correct?'✓':'↻'} ${esc(q.q)}</summary><p>Твой ответ: ${esc(v.answer==='__unknown__'?'Пока не знаю':q.type==='choice'?q.options[Number(v.answer)]||'Без ответа':v.answer||'Без ответа')}</p><p>Разбор: ${esc(q.why)}</p></details>`:''}).join('')}<a class="btn alt" href="#courses/pt/${id}">Повторить тему →</a><p><a href="#courses/pt/${id}">Вернуться к занятию →</a></p></section>`:''}`}else{const q=bank[a.index],answer=a.answers[q.id];body=`<p>Задание ${a.index+1} из ${bank.length} · результат пока не показан</p><progress value="${a.index}" max="${bank.length}" aria-label="Шаг теста"></progress><h2>${esc(q.q)}</h2><form id="test-question">${q.type==='choice'?`<fieldset class="test-options"><legend class="sr-only">Выбери один ответ</legend>${q.options.map((v,i)=>`<label><input type="radio" name="test-choice" value="${i}" ${String(answer)===String(i)?'checked':''}><span>${esc(v)}</span></label>`).join('')}</fieldset>`:`<label>Твой ответ<input id="test-answer" maxlength="300" autocomplete="off" value="${esc(answer==='__unknown__'?'':answer||'')}"></label>`}<div class="row">${a.index?'<button class="btn alt" type="button" id="test-back">← Назад</button>':''}<button class="btn" type="submit">${a.index===4?'Завершить и посмотреть результат':'Дальше →'}</button><button class="btn alt" type="button" id="test-unknown">Пока не знаю</button></div><p id="test-status" role="status"></p></form><p class="small">Ответы сохраняются в аккаунте. Можно вернуться к незавершённой попытке.</p>`}return `<div class="narrow panel"><a class="back" href="#courses/pt/${id}">← К уроку</a><div class="eyebrow">Проверка темы · 5 заданий</div><h1>${esc(l.title)}</h1>${body}</div>`}
function examHome(u){const s=state(u);return `<div class="narrow"><div class="eyebrow">Общая проверка · Бразильский португальский</div><h1>Попробуй формат Celpe-Bras</h1><p>Здесь нужно понимать материалы и использовать язык для реальной задачи: написать письмо, пригласить друга, объяснить позицию и поддержать разговор.</p><div class="notice"><strong>Учебный тренажёр, не официальный экзамен.</strong><p>Все задания Bora авторские, ситуации вымышленные. Видео — учебное слайд-шоу, озвучка синтетическая pt-BR. Это не прошлый вариант INEP и не точная копия процедуры. Разбор ИИ не является официальной оценкой, сертификатом или гарантией сдачи.</p></div><section class="panel"><h2>Письменная часть</h2><p>Четыре задания: видео → письмо, аудио → сообщение и две задачи по прочитанным текстам.</p><p>Пробник: 3 часа. Первые 30 минут — задание 1; затем доступны остальные и возврат к предыдущим ответам. Таймер не останавливается при закрытии вкладки. Видео и аудио — до двух запусков в попытке.</p>${s.written&&!s.written.finishedAt?'<a class="btn" href="#exam/written">Продолжить попытку →</a>':`<div class="row"><button class="btn" id="written-timed">Пробник · 3 часа</button><button class="btn alt" id="written-practice">Учиться без таймера</button></div>`}${s.written?.finishedAt?'<p><a href="#exam/written">Посмотреть последний результат</a></p>':''}</section><section class="panel" style="margin-top:20px"><h2>Устная часть</h2><p>Самостоятельно ответь на вопросы о себе и по трём картинкам. Можно работать без таймера или отвести по пять минут на тему.</p><p class="small">В официальном экзамене нужна живая беседа с экзаменаторами. Здесь доступны только темы и письменные заметки для подготовки.</p>${s.oral&&!s.oral.finishedAt?'<a class="btn" href="#exam/oral">Продолжить подготовку →</a>':'<div class="row"><button class="btn" id="oral-timed">Подготовка · 20 минут</button><button class="btn alt" id="oral-practice">Темы без таймера</button></div>'}${s.oral?.finishedAt?'<p><a href="#exam/oral">Посмотреть сохранённые ответы</a></p>':''}</section>${sources()}</div>`}
function feedbackBlock(a,kind){return `<section class="exam-feedback"><h2>Разбор и следующий шаг</h2><p>Получишь учебные рекомендации по содержанию, задаче, связности и языку. Официальных баллов и решения «экзамен сдан» здесь нет.</p><button class="btn" id="exam-feedback" data-kind="${kind}">${a.feedback?'Обновить разбор':'Получить учебный разбор'}</button><p id="exam-feedback-status" role="status"></p><div class="note-feedback" id="exam-feedback-text">${esc(a.feedback||'')}</div></section>`}
function writtenPage(u){const a=state(u).written;if(!a)return examHome(u);if(a.finishedAt)return `<div class="narrow panel"><a class="back" href="#exam">← Экзамен</a><h1>Письменная попытка сохранена</h1><p>${a.mode==='timed'?'Пробник с таймером':'Учебный режим без таймера'} · ${a.expired?'Время истекло.':'Завершено тобой.'} Ответов: ${D().tasks.filter(t=>a.answers[t.id]?.trim()).length} из 4.</p>${feedbackBlock(a,'written')}${D().tasks.map(t=>`<details><summary>${esc(t.title)}</summary><h3>${esc(t.ptTitle)}</h3><p>${esc(t.prompt)}</p><div class="exam-answer">${esc(a.answers[t.id]||'Ответ не дан')}</div><h3>Что проверить</h3><ul>${t.check.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><details><summary>Исходный материал / расшифровка</summary><p>${esc(t.text||t.transcript)}</p></details></details>`).join('')}<p class="small">Разбор может ошибаться; спорные места стоит проверить с преподавателем.</p><a class="btn alt" href="#exam">К устной части →</a>${sources()}</div>`;const t=D().tasks[a.index||0],phase=a.mode==='timed'&&Date.now()-Date.parse(a.startedAt)<1800000;return `<div class="narrow panel"><a class="back" href="#exam">← К разделу экзамена</a><div class="exam-clock"><strong>${a.mode==='timed'?'Пробник · письменная часть':'Учебный режим'}</strong><span id="exam-countdown" role="timer">${a.deadlineAt?time(remaining(a)):'Без таймера'}</span></div><p class="small">${phase?'Первые 30 минут: работаем с видео. Остальные задания откроются автоматически.':'Можно возвращаться к заданиям и редактировать ответы до завершения.'}</p><div class="exam-task-nav" role="group" aria-label="Задание письменной части">${D().tasks.map((t,i)=>`<button class="btn alt" data-written-task="${i}" aria-pressed="${i===a.index}" ${phase&&i>0?'disabled':''}>${i+1}. ${['Видео','Аудио','Текст','Мнение'][i]}</button>`).join('')}</div><h1>${esc(t.title)}</h1><h2 lang="pt-BR">${esc(t.ptTitle)}</h2>${t.type==='text'?`<article class="exam-source" lang="pt-BR">${esc(t.text)}</article>`:`<${t.type} id="exam-media" controls preload="metadata" ${t.type==='video'?'playsinline':''} src="${t.media}" aria-label="${t.type==='video'?'Учебное видео':'Учебное аудио'} на бразильском португальском"></${t.type}><p class="small">Авторский материал Bora, синтетический голос pt-BR. Использовано запусков: <span id="media-play-count">${a.plays[t.id]||0}</span> из 2. Переход на другой экран прерывает запуск; пауза и продолжение на этом экране не расходуют дополнительный.</p><p id="exam-media-status" role="status"></p>`}<div class="exam-prompt" lang="pt-BR">${esc(t.prompt)}</div>${a.mode==='practice'?`<details><summary>Понять задание по-русски</summary><p>${esc(t.help)}</p></details>`:''}<label for="written-answer">Твой текст на португальском</label><textarea id="written-answer" maxlength="3500" rows="12" placeholder="Escreva seu texto aqui…">${esc(a.answers[t.id]||'')}</textarea><p class="small"><span id="written-word-count">${String(a.answers[t.id]||'').trim().split(/\s+/).filter(Boolean).length}</span> слов. Важны адресат, цель и содержание, а не только длина. До 3500 символов в этом тренажёре.</p><p class="small">Черновик сохраняется в аккаунте. Перед выходом дождись «Сохранено в базе».</p><div class="row"><button class="btn alt" id="written-finish">Завершить попытку и перейти к разбору</button></div>${sources()}</div>`}
function oralPage(u){const a=state(u).oral;if(!a)return examHome(u);if(a.finishedAt)return `<div class="narrow panel"><a class="back" href="#exam">← К пробнику</a><h1>Ответы сохранены</h1><p>Это самостоятельная подготовка: произношение и разговор с экзаменатором здесь не проверяются.</p>${feedbackBlock(a,'oral')}<details><summary>Мои ответы</summary>${a.messages.filter(m=>m.role==='user').map(m=>`<p>${esc(D().oral[m.stage]?.title)}: ${esc(m.content)}</p>`).join('')}</details></div>`;const stage=oralStage(a),p=D().oral[stage],photo=window.BoraLessonPhotos?.[p.image];return `<div class="narrow panel"><a class="back" href="#exam">← Сохранить и вернуться к пробнику</a><div class="exam-clock"><strong>Самостоятельная подготовка</strong><span id="exam-countdown" role="timer">${a.deadlineAt?time(remaining(a)):'Без таймера'}</span></div><p>Тема ${stage+1} из 4 · ${esc(p.title)}</p>${photo?`<img class="oral-stimulus" src="${photo.src}" alt="${esc(photo.place)}" width="960" height="540">`:''}<p class="exam-prompt" lang="pt-BR">${esc(p.opening)}</p><p>Ответь вслух для себя, затем запиши основные мысли. Голосовой помощник отключён.</p><form id="oral-self-form"><label>Мой ответ<textarea id="oral-self-input" maxlength="1200">${esc(a.messages.find(m=>m.role==='user'&&m.stage===stage)?.content||'')}</textarea></label></form><p class="small">Ответ сохраняется автоматически. Это тренировка темы, а не оценка устной речи.</p><div class="row">${a.mode==='practice'&&stage<3?'<button class="btn" id="oral-self-next">Следующая тема →</button>':''}<button class="btn alt" id="oral-self-finish">Завершить подготовку</button></div></div>`}

function page(u){const parts=location.hash.slice(1).split('/');return parts[0]==='test'?quizPage(u,parts[1]):parts[1]==='written'?writtenPage(u):parts[1]==='oral'?oralPage(u):examHome(u)}
function bind(u,save,render){const $=s=>document.querySelector(s),on=(s,f)=>{const e=$(s);if(e)e.onclick=f};if(!['test','exam'].includes(location.hash.slice(1).split('/')[0]))return;let alive=true;const disposers=[];cleanup=()=>{alive=false;disposers.forEach(f=>f())};const every=f=>{const id=setInterval(f,1000);disposers.push(()=>clearInterval(id));f()};
const id=location.hash.split('/')[1];if(location.hash.startsWith('#test/')){const r=record(u,id),bank=window.BoraLessonTests.bank(id);if(!bank.length)return;on('#test-start',()=>{if(r.last)r.history=[...r.history,r.last].slice(-3);r.draft={id:uid(),index:0,answers:{},startedAt:Date.now()};save();render()});if(r.draft){const a=r.draft,q=bank[a.index],input=$('#test-answer');if(input)input.oninput=()=>{a.answers[q.id]=input.value;save()};document.querySelectorAll('[name="test-choice"]').forEach(e=>e.onchange=()=>{a.answers[q.id]=e.value;save()});const next=unknown=>{if(unknown)a.answers[q.id]='__unknown__';else if(a.answers[q.id]===undefined||!String(a.answers[q.id]).trim()){$('#test-status').textContent='Выбери ответ или нажми «Пока не знаю».';return}if(a.index<4)a.index++;else{r.last={...window.BoraLessonTests.grade(id,a.answers),id:a.id,at:Date.now()};r.draft=null}save();render()};$('#test-question').onsubmit=e=>{e.preventDefault();next(false)};on('#test-unknown',()=>next(true));on('#test-back',()=>{a.index--;save();render()})}return}
for(const kind of ['written','oral'])for(const mode of ['timed','practice'])on('#'+kind+'-'+mode,()=>{const s=state(u);if(s[kind]&&!s[kind].finishedAt){location.hash='exam/'+kind;return}if(s[kind])s[kind+'History']=[...(s[kind+'History']||[]),s[kind]].slice(-2);s[kind]=kind==='written'?newWritten(mode):newOral(mode);save();location.hash='exam/'+kind});
on('#exam-feedback',async()=>{const b=$('#exam-feedback'),kind=b.dataset.kind,a=state(u)[kind],out=$('#exam-feedback-status'),text=$('#exam-feedback-text'),controller=new AbortController();disposers.push(()=>controller.abort());b.disabled=true;out.textContent='Сохраняю ответы и готовлю разбор…';try{await window.BoraAccount.flush();const response=await fetch('/api/exam-feedback',{method:'POST',headers:await window.BoraAccount.apiHeaders(),body:JSON.stringify({kind,attemptId:a.id}),signal:AbortSignal.any([controller.signal,AbortSignal.timeout(110000)])}),v=await response.json();if(!response.ok)throw Error(v.error||'Разбор пока недоступен');if(!alive||state(u)[kind]?.id!==a.id)return;a.feedback=v.feedback;save();text.textContent=v.feedback;b.textContent='Обновить разбор';out.textContent='Учебный разбор готов. Модель может ошибаться.'}catch(e){if(alive)out.textContent=e.name==='AbortError'?'Разбор прерван. Ответы сохранены; попробуй ещё раз.':e.message}finally{if(alive)b.disabled=false}});
const written=state(u).written;if($('#written-answer')&&written&&!written.finishedAt){const a=written,t=D().tasks[a.index],input=$('#written-answer');input.oninput=()=>{a.answers[t.id]=input.value;$('#written-word-count').textContent=input.value.trim().split(/\s+/).filter(Boolean).length;save()};document.querySelectorAll('[data-written-task]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.writtenTask);if(a.mode==='timed'&&Date.now()-Date.parse(a.startedAt)<1800000&&i>0)return;a.index=i;save();render()});on('#written-finish',()=>{if(!confirm('Завершить письменную попытку? Редактировать ответы после завершения нельзя.'))return;finishWritten(a);save();render()});let firstPhase=a.mode==='timed'&&Date.now()-Date.parse(a.startedAt)<1800000;every(()=>{if(a.deadlineAt){$('#exam-countdown').textContent=time(remaining(a));if(remaining(a)===0){finishWritten(a);save();render();return}const phase=Date.now()-Date.parse(a.startedAt)<1800000;if(phase!==firstPhase){firstPhase=phase;render()}}});const media=$('#exam-media');if(media){let running=false;media.onplay=()=>{if(running)return;if((a.plays[t.id]||0)>=2){media.pause();$('#exam-media-status').textContent='Два запуска использованы. Расшифровка будет доступна после завершения.';return}a.plays[t.id]=(a.plays[t.id]||0)+1;running=true;$('#media-play-count').textContent=a.plays[t.id];save()};media.onended=()=>{running=false};media.onerror=()=>{$('#exam-media-status').textContent='Материал не загрузился. Проверь соединение и повтори воспроизведение.'};disposers.push(()=>{media.onplay=media.onended=media.onerror=null;media.pause()})}return}
const self=state(u).oral;if($('#oral-self-form')&&self&&!self.finishedAt){const stage=oralStage(self),input=$('#oral-self-input');input.oninput=()=>{self.messages=self.messages.filter(m=>!(m.role==='user'&&m.stage===stage));if(input.value.trim())self.messages.push({role:'user',stage,content:input.value.slice(0,1200),at:Date.now()});save()};on('#oral-self-next',()=>{self.stage=Math.min(3,stage+1);save();render()});on('#oral-self-finish',()=>{finishOral(self);save();render()});every(()=>{if(!self.deadlineAt)return;$('#exam-countdown').textContent=time(remaining(self));if(remaining(self)===0){finishOral(self);save();render()}else if(oralStage(self)!==stage){save();render()}});return}

}
window.BoraAssess={page,bind,stop,progress,newWritten,finishWritten,remaining,newOral,oralStage,finishOral};
})();
